    "s1.heading": "1. Inligting wat verkry moet word",
    "s1.body": "<strong>Hierdie toepassing versamel of stuur nie inligting wat individuele gebruikers, gebruikstatistieke, mediese inligting of pasiëntinligting na die ontwikkelaar se bediener kan identifiseer nie.</strong>",
