    "s4.heading": "4. Die verskaffing van inligting aan derde partye",
    "s4.body": "Hierdie toepassing samel nie gebruikers se persoonlike inligting, mediese inligting of pasiëntinligting op die ontwikkelaar se bediener in nie, so die ontwikkelaar sal nie hierdie inligting aan derde partye verskaf nie. Ons gebruik ook nie derdeparty-biblioteke vir advertering, opsporing of eie analise nie.",
