    "header.updated": "Последна актуализирана дата",
    "header.date": "20 май 2026 г",
    "intro": "Fumikazu Kondo (наричан по-нататък „Разработчик“) счита защитата на поверителността на потребителите на iOS и Android версията на приложението „Болница/Спешна помощ Waku-kun Board“ (наричано по-нататък „Приложението“) за изключително важна. Тази политика обяснява как информацията се обработва от това приложение.",
    "s1.heading": "1. Информация, която трябва да се получи",
    "s1.body": "<strong>Това приложение не събира и не изпраща информация, която може да идентифицира отделни потребители, статистически данни за употребата, медицинска информация или информация за пациента до сървъра на разработчика.</strong>",
    "s2.heading": "2. Информация, съхранена на вашето устройство",
    "s2.body": "Това приложение запазва следната информация на устройството на потребителя. Те никога не се изпращат до сървърите на разработчика.",
    "s2.item1": "Избран език на дисплея",
    "s2.item2": "Настройки на дисплея, като например дисплей на фуригана",
    "s2.item3": "Предварително записани медицински фрази и редактирани/добавени от потребителя фрази",
