    "s2.item6": "Състояние на покупка на покупки в приложението (професионални функции) във версия на iOS",
    "s3.heading": "3. Мрежова комуникация",
    "s3.body1": "Прегледът на основните фрази на това приложение, търсенето, показването на категории, любимите, сортирането и запазването на редактирано съдържание работят в рамките на устройството.",
    "s3.body2": "Версията на iOS комуникира само със сървърите на Apple (StoreKit) при закупуване на покупки в приложението или възстановяване на покупки. Това използва стандартната платформа за плащане, управлявана от Apple, и това приложение не улавя никаква информация за плащане.",
    "s4.heading": "4. Предоставяне на информация на трети страни",
    "s4.body": "Това приложение не събира лична информация на потребителите, медицинска информация или информация за пациенти на сървъра на разработчика, така че разработчикът няма да предоставя тази информация на трети страни. Също така не използваме библиотеки на трети страни за реклама, проследяване или собствени анализи.",
    "s5.heading": "5. Използване от деца",
    "s5.body": "Това приложение не събира лична информация на сървъра на разработчика, така че може да се използва от хора от всички възрасти. Това приложение обаче е предназначено да подпомага комуникацията в медицински условия и при посещение при лекар и не е предназначено предимно за деца.",
    "s6.heading": "6. Как да изтриете данни",
    "s6.body1": "Ако деинсталирате това приложение, данните, записани на вашето устройство (редактирани фрази, любими, настройки и т.н.), ще бъдат изтрити.",
    "s6.body2": "Историята на покупките на покупките в приложението за версията на iOS е свързана с вашия Apple ID и се съхранява на сървърите на Apple и можете да я активирате отново, като щракнете върху „Възстановяване на покупките“, когато преинсталирате приложението. Това се управлява от Apple, а не от приложението.",
    "s7.heading": "7. Забележка относно медицинска информация",
    "s7.body": "Това приложение е инструмент за подпомагане на текстовата комуникация с медицински специалисти. Не е предназначен да диагностицира, да определя планове за лечение или да прави преценки при спешни случаи. В случай на спешност, моля, следвайте инструкциите на медицинския персонал и службите за спешна помощ.",
    "s8.heading": "8. Ревизия на политиката",
    "s8.body": "Тази политика може да бъде преразгледана при необходимост. Ако има важни промени, ще ви уведомим на тази страница.",
    "back": "← Назад към страницата за поддръжка",
    "footer.copyright": "© 2026 Fumikazu Kondo. Всички права запазени.",
