    "s3.body3": "Версията за Android не осъществява комуникация за покупки или абонаменти в приложението. Комуникация с Google или системните услуги на вашето устройство обаче може да възникне в следните случаи:",
    "s3.item1": "Изтеглете или подгответе модел за превод на ML Kit",
    "s3.item2": "Търсене по фраза чрез гласово въвеждане",
    "s3.item3": "Комуникация за диагностика и поддържане на съвместимост от Android система или Google Play услуги",
    "s3.audio": "Гласовото въвеждане във версията за Android е за въвеждане на думи за търсене чрез функцията за гласово разпознаване на устройството. Това приложение не запазва аудио данни.",
    "s4.body2": "Въпреки това, SDK като Google ML Kit, използвани във версията за Android и услугите за гласово разпознаване на устройства, могат да обработват информация за устройството, информация за приложението, информация за грешки, езици за настройка на превода и т.н. в обхвата, определен от Google за цели като изтегляне на модел, диагностика и поддръжка на качеството. Тези обработки са предмет на политиката за поверителност на Google и спецификациите на всяка услуга.",
    "s6.android": "Версията за Android в момента няма покупки в приложението или функции за абонамент.",
    "s9.heading": "9. Свържете се с нас",
    "s9.body": "За запитвания относно тази политика или обработката на информация в това приложение, моля, свържете се с нас по-долу."
