    "header.date": "20 de maig de 2026",
    "intro": "Fumikazu Kondo (d'ara endavant, el \"Desenvolupador\") considera extremadament important la protecció de la privadesa dels usuaris de la versió per a iOS i Android de l'aplicació \"Hospital/Emergency Waku-kun Board\" (d'ara endavant denominada \"Aplicació\"). Aquesta política explica com aquesta aplicació gestiona la informació.",
    "s1.heading": "1. Informació a obtenir",
    "s1.body": "<strong>Aquesta aplicació no recopila ni envia informació que pugui identificar usuaris individuals, estadístiques d'ús, informació mèdica o informació del pacient al servidor del desenvolupador.</strong>",
    "s2.heading": "2. Informació emmagatzemada al dispositiu",
