    "s3.heading": "3. Comunicació en xarxa",
    "s3.body1": "La visualització de frases bàsiques d'aquesta aplicació, la cerca, la visualització de categories, els preferits, l'ordenació i l'emmagatzematge del contingut editat operen dins del dispositiu.",
    "s3.body2": "La versió d'iOS només es comunica amb els servidors d'Apple (StoreKit) en comprar compres des de l'aplicació o en restaurar compres. Això utilitza la plataforma de pagament estàndard operada per Apple i aquesta aplicació no captura cap informació de pagament.",
    "s4.heading": "4. Facilitar informació a tercers",
    "s4.body": "Aquesta aplicació no recopila informació personal dels usuaris, informació mèdica o informació del pacient al servidor del desenvolupador, de manera que el desenvolupador no proporcionarà aquesta informació a tercers. Tampoc utilitzem biblioteques de tercers per a publicitat, seguiment o anàlisi de propietat.",
    "s5.heading": "5. Ús pels nens",
    "s5.body": "Aquesta aplicació no recull informació personal al servidor del desenvolupador, de manera que la poden utilitzar persones de totes les edats. Tanmateix, aquesta aplicació està pensada per ajudar a la comunicació en entorns mèdics i quan visiteu un metge, i no està dissenyada principalment per a nens.",
    "s6.heading": "6. Com esborrar dades",
    "s6.body1": "Si desinstal·les aquesta aplicació, s'eliminaran les dades desades al teu dispositiu (frases editades, preferits, paràmetres, etc.).",
    "s6.body2": "L'historial de compres de compres integrades a l'aplicació per a la versió d'iOS està vinculat al vostre ID d'Apple i s'emmagatzema als servidors d'Apple, i podeu reactivar-lo fent clic a \"Restaura les compres\" quan torneu a instal·lar l'aplicació. Això ho gestiona Apple, no l'aplicació.",
    "s7.heading": "7. Avís sobre informació mèdica",
    "s7.body": "Aquesta aplicació és una eina per facilitar la comunicació de text amb professionals mèdics. No està pensat per diagnosticar, determinar plans de tractament o fer judicis en cas d'emergència. En cas d'emergència, seguiu les instruccions del personal mèdic i dels serveis d'emergència.",
    "s8.heading": "8. Revisió de la política",
