    "intro": "Mae Fumikazu Kondo (y cyfeirir ati o hyn ymlaen fel y `` Datblygwr '') yn ystyried bod amddiffyniad preifatrwydd defnyddwyr fersiwn iOS ac Android o'r ap \"Ysbyty / Bwrdd Waku-kun Argyfwng\" (y cyfeirir ato o hyn ymlaen fel yr `` App '') yn hynod bwysig. Mae'r polisi hwn yn esbonio sut mae gwybodaeth yn cael ei thrin gan yr ap hwn.",
