    "intro": "Fumikazu Kondo (herefter benævnt ``Udvikleren'') anser privatlivets fred for brugere af iOS- og Android-versionen af ​​appen ``Hospital/Emergency Waku-kun Board'' (herefter benævnt ``App'') for at være ekstremt vigtig. Denne politik forklarer, hvordan oplysninger håndteres af denne app.",
