    "s6.body2": "Το ιστορικό αγορών για αγορές εντός εφαρμογής για την έκδοση iOS συνδέεται με το Apple ID σας και αποθηκεύεται στους διακομιστές της Apple και μπορείτε να το ενεργοποιήσετε ξανά κάνοντας κλικ στην \"Επαναφορά αγορών\" κατά την επανεγκατάσταση της εφαρμογής. Αυτό το διαχειρίζεται η Apple, όχι η εφαρμογή.",
