    "s7.body": "Αυτή η εφαρμογή είναι ένα εργαλείο για να βοηθήσει την επικοινωνία κειμένου με επαγγελματίες του ιατρικού τομέα. Δεν προορίζεται για τη διάγνωση, τον καθορισμό σχεδίων θεραπείας ή τη λήψη κρίσεων σε καταστάσεις έκτακτης ανάγκης. Σε περίπτωση έκτακτης ανάγκης, ακολουθήστε τις οδηγίες του ιατρικού προσωπικού και των υπηρεσιών έκτακτης ανάγκης.",
    "s8.heading": "8. Αναθεώρηση πολιτικής",
    "s8.body": "Αυτή η πολιτική μπορεί να αναθεωρηθεί όπως απαιτείται. Εάν υπάρχουν σημαντικές αλλαγές, θα σας ειδοποιήσουμε σε αυτήν τη σελίδα.",
    "back": "← Επιστροφή στη σελίδα υποστήριξης",
    "footer.copyright": "© 2026 Fumikazu Kondo. Με την επιφύλαξη παντός δικαιώματος.",
    "s2.android": "Η έκδοση Android αυτή τη στιγμή δεν διαθέτει αγορές εντός εφαρμογής ή λειτουργίες συνδρομής.",
    "s3.body3": "Η έκδοση Android δεν πραγματοποιεί επικοινωνία για αγορές εντός εφαρμογής ή συνδρομές. Ωστόσο, η επικοινωνία με την Google ή τις υπηρεσίες συστήματος της συσκευής σας μπορεί να προκύψει στις ακόλουθες περιπτώσεις:",
    "s3.item1": "Κατεβάστε ή προετοιμάστε ένα μοντέλο μετάφρασης ML Kit",
    "s3.item2": "Αναζήτηση φράσεων με φωνητική εισαγωγή",
    "s3.item3": "Επικοινωνία για διάγνωση και συντήρηση συμβατότητας από σύστημα Android ή υπηρεσίες Google Play",
    "s3.audio": "Η φωνητική είσοδος στην έκδοση Android είναι για την εισαγωγή όρων αναζήτησης χρησιμοποιώντας τη λειτουργία αναγνώρισης φωνής της συσκευής. Αυτή η εφαρμογή δεν αποθηκεύει δεδομένα ήχου.",
    "s4.body2": "Ωστόσο, τα SDK όπως το Google ML Kit που χρησιμοποιούνται στην έκδοση Android και οι υπηρεσίες αναγνώρισης φωνής σε συσκευές ενδέχεται να χειρίζονται πληροφορίες συσκευής, πληροφορίες εφαρμογής, πληροφορίες σφαλμάτων, γλώσσες ρύθμισης μετάφρασης κ.λπ. εντός του πεδίου που καθορίζει η Google για σκοπούς όπως λήψη μοντέλου, διάγνωση και συντήρηση ποιότητας. Αυτές οι θεραπείες υπόκεινται στην πολιτική απορρήτου της Google και στις προδιαγραφές κάθε υπηρεσίας.",
    "s6.android": "Η έκδοση Android αυτή τη στιγμή δεν διαθέτει αγορές εντός εφαρμογής ή λειτουργίες συνδρομής.",
    "s9.heading": "9. Επικοινωνήστε μαζί μας",
    "s9.body": "Για ερωτήσεις σχετικά με αυτήν την πολιτική ή τον χειρισμό πληροφοριών σε αυτήν την εφαρμογή, επικοινωνήστε μαζί μας παρακάτω."
