  dict.privacy["ga"] = {
    "page.title": "Bord tuisceana ospidéil/éigeandála — Beartas príobháideachta",
    "header.title": "Beartas príobháideachta",
    "header.subtitle": "Bord tuisceana ospidéil/éigeandála",
    "header.updated": "Dáta nuashonraithe is déanaí",
    "header.date": "20 Bealtaine, 2026",
    "intro": "Measann Fumikazu Kondo (dá ngairtear an ``Forbróir'' anseo feasta) go bhfuil cosaint phríobháideachta úsáideoirí leagan iOS agus Android den aip ``Ospital/Emergency Waku-kun Board'' (dá ngairfear an ``App'' anseo feasta) thar a bheith tábhachtach. Míníonn an polasaí seo conas a láimhseálann an aip seo faisnéis.",
    "s1.heading": "1. Faisnéis le fáil",
    "s1.body": "<strong>Ní bhailíonn nó ní sheolann an aip seo faisnéis ar féidir úsáideoirí aonair, staitisticí úsáide, faisnéis leighis nó faisnéis othar a shainaithint chuig freastalaí an fhorbróra.</strong>",
    "s2.heading": "2. Faisnéis atá stóráilte ar do ghléas",
    "s2.body": "Sábhálann an feidhmchlár seo an fhaisnéis seo a leanas ar ghléas an úsáideora. Ní sheoltar iad seo riamh chuig freastalaithe an fhorbróra.",
    "s2.item1": "Teanga taispeána roghnaithe",
    "s2.item2": "Socruithe taispeána ar nós taispeáint furigana",
    "s2.item3": "Frásaí leighis réamhthaifeadta agus frásaí arna gcur in eagar ag an úsáideoir/curtha leis",
    "s2.item4": "Cibé an bhfuil nó nach bhfuil sé cláraithe mar is fearr leat, agus an t-ord ina bhfuil sé liostaithe sa is fearr leat",
    "s2.item5": "Ord sórtála catagóirí agus frásaí",
    "s2.item6": "Stádas ceannacháin in-app (gnéithe Pro) sa leagan iOS",
    "s3.heading": "3. Cumarsáid líonra",
    "s3.body1": "Feidhmíonn amharc frása bunúsach an aip seo, cuardach, taispeáint chatagóirí, ceanáin, sórtáil agus sábháil ábhar in eagar laistigh den ghléas.",
    "s3.body2": "Ní dhéanann an leagan iOS cumarsáid ach le freastalaithe Apple (StoreKit) nuair a cheannaítear ceannacháin in-app nó nuair a dhéantar ceannacháin a athchóiriú. Úsáideann sé seo an t-ardán íocaíochta caighdeánach arna oibriú ag Apple, agus ní ghlacann an app aon fhaisnéis íocaíochta.",
    "s4.heading": "4. Faisnéis a sholáthar do thríú páirtithe",
    "s4.body": "Ní bhailíonn an aip seo faisnéis phearsanta úsáideoirí, faisnéis leighis, nó faisnéis othar ar fhreastalaí an fhorbróra, mar sin ní chuirfidh an forbróir an fhaisnéis seo ar fáil do thríú páirtithe. Ní úsáidimid leabharlanna tríú páirtí ach an oiread le haghaidh fógraíochta, rianaithe nó anailísíochta dílseánaigh.",
    "s5.heading": "5. Úsáid ag leanaí",
    "s5.body": "Ní bhailíonn an aip seo faisnéis phearsanta ar fhreastalaí an fhorbróra, mar sin is féidir le daoine de gach aois í a úsáid. Mar sin féin, tá an aip seo beartaithe chun cabhrú le cumarsáid i suíomhanna leighis agus le linn cuairt a thabhairt ar dhochtúir, agus níl sé deartha go príomha do leanaí.",
    "s6.heading": "6. Conas sonraí a scriosadh",
    "s6.body1": "Má dhíshuiteálann tú an aip seo, scriosfar na sonraí a shábháiltear ar do ghléas (frásaí curtha in eagar, ceanáin, socruithe, srl.).",
    "s6.body2": "Tá stair cheannaigh do cheannacháin in-app don leagan iOS ceangailte le do ID Apple agus stóráilte ar fhreastalaithe Apple, agus is féidir leat é a athghníomhachtú trí chliceáil ar \"Athchóirigh Ceannaigh\" nuair a athshuiteálann tú an aip. Tá sé seo á bhainistiú ag Apple, ní an app.",
    "s7.heading": "7. Fógra maidir le faisnéis leighis",
    "s7.body": "Is uirlis í an aip seo chun cuidiú le cumarsáid téacs le gairmithe leighis. Níl sé i gceist diagnóis a dhéanamh, pleananna cóireála a chinneadh, ná breithiúnais a dhéanamh i gcásanna éigeandála. I gcás éigeandála, lean treoracha an phearsanra leighis agus na seirbhísí éigeandála.",
    "s8.heading": "8. Leasú beartais",
    "s8.body": "Féadfar an polasaí seo a athbhreithniú de réir mar is gá. Má tá aon athruithe tábhachtacha, cuirfimid tú ar an eolas ar an leathanach seo.",
    "back": "← Fill ar an leathanach tacaíochta",
    "footer.copyright": "© 2026 Fumikazu Kondo. Gach ceart ar cosaint.",
    "s2.android": "Níl ceannacháin in-aip nó gnéithe síntiúis ag an leagan Android faoi láthair.",
    "s3.body3": "Ní fheidhmíonn an leagan Android cumarsáid le haghaidh ceannacháin nó síntiúis in-app. D’fhéadfadh cumarsáid le Google nó le seirbhísí córais do ghléis tarlú sna cásanna seo a leanas, áfach:",
    "s3.item1": "Íoslódáil nó ullmhaigh samhail aistriúcháin ML Kit",
    "s3.item2": "Cuardach frása de réir ionchur gutha",
    "s3.item3": "Cumarsáid le haghaidh diagnóis agus cothabháil comhoiriúnachta ag córas Android nó seirbhísí Google Play",
    "s3.audio": "Tá ionchur gutha ar an leagan Android chun téarmaí cuardaigh a ionchur ag baint úsáide as feidhm aitheantais gutha an ghléis. Ní shábhálann an aip seo sonraí fuaime.",
    "s4.body2": "Mar sin féin, féadfaidh SDKanna ar nós Google ML Kit a úsáidtear sa leagan Android agus seirbhísí aitheantais gutha ar fheistí faisnéis gléis, faisnéis feidhmchláir, faisnéis earráide, teangacha socruithe aistriúcháin, etc. a láimhseáil laistigh den raon feidhme arna chinneadh ag Google chun críocha amhail íoslódáil samhail, diagnóis agus cothabháil cáilíochta. Tá na cóireálacha seo faoi réir bheartas príobháideachais Google agus sonraíochtaí gach seirbhíse.",
    "s6.android": "Níl ceannacháin in-aip nó gnéithe síntiúis ag an leagan Android faoi láthair.",
    "s9.heading": "9. Déan teagmháil linn",
    "s9.body": "Le haghaidh fiosrúcháin maidir leis an mbeartas seo nó maidir le láimhseáil faisnéise san aip seo, déan teagmháil linn thíos."
  };

