    "s4.heading": "4. Facilitar información a terceiros",
    "s4.body": "Esta aplicación non recolle información persoal dos usuarios, información médica ou información do paciente no servidor do programador, polo que o programador non proporcionará esta información a terceiros. Tampouco utilizamos bibliotecas de terceiros para publicidade, seguimento ou análise de propiedade.",
    "s5.heading": "5. Uso por nenos",
    "s5.body": "Esta aplicación non recolle información persoal no servidor do programador, polo que pode ser usada por persoas de todas as idades. Non obstante, esta aplicación está destinada a facilitar a comunicación en ámbitos médicos e cando se visita a un médico, e non está deseñada principalmente para nenos.",
    "s6.heading": "6. Como eliminar datos",
    "s6.body1": "Se desinstalas esta aplicación, eliminaranse os datos gardados no teu dispositivo (frases editadas, favoritos, configuracións, etc.).",
    "s6.body2": "O historial de compras para compras integradas na aplicación para a versión de iOS está ligado ao teu ID de Apple e almacénase nos servidores de Apple, e podes reactivalo facendo clic en \"Restaurar compras\" cando reinstales a aplicación. Isto é xestionado por Apple, non pola aplicación.",
    "s7.heading": "7. Aviso sobre información médica",
    "s7.body": "Esta aplicación é unha ferramenta para axudar a comunicación de texto con profesionais médicos. Non se pretende diagnosticar, determinar plans de tratamento ou emitir xuízos en emerxencias. En caso de emerxencia, siga as instrucións do persoal médico e dos servizos de emerxencia.",
    "s8.heading": "8. Revisión da política",
    "s8.body": "Esta política pode ser revisada segundo sexa necesario. Se hai algún cambio importante, avisarémosche nesta páxina.",
