    "header.updated": "છેલ્લી અપડેટ તારીખ",
    "header.date": "20 મે, 2026",
    "intro": "Fumikazu Kondo (ત્યારબાદ ``વિકાસકર્તા'' તરીકે ઓળખાય છે) એપ ``હોસ્પિટલ/ઇમર્જન્સી વાકુ-કુન બોર્ડ'' (ત્યારબાદ ``એપ'' તરીકે ઓળખાય છે)ના iOS અને Android સંસ્કરણના વપરાશકર્તાઓની ગોપનીયતા સુરક્ષાને અત્યંત મહત્ત્વપૂર્ણ માને છે. આ નીતિ સમજાવે છે કે આ એપ્લિકેશન દ્વારા માહિતી કેવી રીતે હેન્ડલ કરવામાં આવે છે.",
    "s1.heading": "1. માહિતી મેળવવાની રહેશે",
    "s1.body": "<strong>આ એપ્લિકેશન એવી માહિતી એકત્રિત કરતી નથી કે મોકલતી નથી કે જે વ્યક્તિગત વપરાશકર્તાઓ, ઉપયોગના આંકડા, તબીબી માહિતી અથવા દર્દીની માહિતી વિકાસકર્તાના સર્વરને ઓળખી શકે.</strong>",
    "s2.heading": "2. તમારા ઉપકરણ પર સંગ્રહિત માહિતી",
    "s2.body": "આ એપ્લિકેશન નીચેની માહિતીને વપરાશકર્તાના ઉપકરણ પર સાચવે છે. આ ક્યારેય વિકાસકર્તાના સર્વર પર મોકલવામાં આવતા નથી.",
    "s2.item1": "પસંદ કરેલ પ્રદર્શન ભાષા",
    "s2.item2": "ડિસ્પ્લે સેટિંગ્સ જેમ કે ફુરિગાના ડિસ્પ્લે",
    "s2.item3": "પૂર્વ-રેકોર્ડ કરેલ તબીબી શબ્દસમૂહો અને વપરાશકર્તા દ્વારા સંપાદિત/ઉમેરેલા શબ્દસમૂહો",
    "s2.item4": "તે મનપસંદ તરીકે નોંધાયેલ છે કે નહીં, અને જે ક્રમમાં તે મનપસંદમાં સૂચિબદ્ધ છે",
    "s2.item5": "શ્રેણીઓ અને શબ્દસમૂહોનો ક્રમ સૉર્ટ કરો",
    "s2.item6": "iOS સંસ્કરણમાં ઇન-એપ ખરીદીઓ (પ્રો સુવિધાઓ) ની ખરીદીની સ્થિતિ",
    "s3.heading": "3. નેટવર્ક સંચાર",
    "s3.body1": "આ એપ્લિકેશનનું મૂળભૂત શબ્દસમૂહ જોવા, શોધવું, કેટેગરી ડિસ્પ્લે, મનપસંદ, સૉર્ટિંગ અને સંપાદિત સામગ્રીને સાચવવાનું ઉપકરણની અંદર કાર્ય કરે છે.",
    "s3.body2": "એપ્લિકેશનમાં ખરીદી કરતી વખતે અથવા ખરીદીને પુનઃસ્થાપિત કરતી વખતે iOS સંસ્કરણ ફક્ત Appleના સર્વર (સ્ટોરકિટ) સાથે વાતચીત કરે છે. આ Apple દ્વારા સંચાલિત પ્રમાણભૂત ચુકવણી પ્લેટફોર્મનો ઉપયોગ કરે છે, અને એપ્લિકેશન કોઈપણ ચુકવણી માહિતીને કેપ્ચર કરતી નથી.",
    "s4.heading": "4. તૃતીય પક્ષોને માહિતી પૂરી પાડવી",
    "s4.body": "આ એપ્લિકેશન વિકાસકર્તાના સર્વર પર વપરાશકર્તાઓની વ્યક્તિગત માહિતી, તબીબી માહિતી અથવા દર્દીની માહિતી એકત્રિત કરતી નથી, તેથી વિકાસકર્તા તૃતીય પક્ષોને આ માહિતી પ્રદાન કરશે નહીં. અમે જાહેરાત, ટ્રેકિંગ અથવા માલિકીના વિશ્લેષણ માટે તૃતીય-પક્ષ પુસ્તકાલયોનો પણ ઉપયોગ કરતા નથી.",
    "s5.heading": "5. બાળકો દ્વારા ઉપયોગ કરો",
    "s5.body": "આ એપ્લિકેશન વિકાસકર્તાના સર્વર પર વ્યક્તિગત માહિતી એકત્રિત કરતી નથી, તેથી તેનો ઉપયોગ તમામ ઉંમરના લોકો કરી શકે છે. જો કે, આ એપ્લિકેશનનો હેતુ તબીબી સેટિંગ્સમાં અને ડૉક્ટરની મુલાકાત લેતી વખતે સંચાર કરવામાં મદદ કરવાનો છે, અને તે મુખ્યત્વે બાળકો માટે રચાયેલ નથી.",
    "s6.heading": "6. ડેટા કેવી રીતે કાઢી નાખવો",
    "s6.body1": "જો તમે આ એપ્લિકેશનને અનઇન્સ્ટોલ કરો છો, તો તમારા ઉપકરણ પર સાચવેલ ડેટા (સંપાદિત શબ્દસમૂહો, મનપસંદ, સેટિંગ્સ, વગેરે) કાઢી નાખવામાં આવશે.",
    "s6.body2": "iOS સંસ્કરણ માટે એપ્લિકેશનમાં ખરીદીઓ માટેનો ખરીદીનો ઇતિહાસ તમારા Apple ID સાથે જોડાયેલ છે અને Appleના સર્વર્સ પર સંગ્રહિત છે, અને તમે એપ્લિકેશનને ફરીથી ઇન્સ્ટોલ કરતી વખતે \"રીસ્ટોર ખરીદીઓ\" પર ક્લિક કરીને તેને ફરીથી સક્રિય કરી શકો છો. આ Apple દ્વારા સંચાલિત થાય છે, એપ્લિકેશન દ્વારા નહીં.",
    "s7.heading": "7. તબીબી માહિતી સંબંધિત સૂચના",
    "s7.body": "આ એપ્લિકેશન તબીબી વ્યાવસાયિકો સાથે ટેક્સ્ટ સંદેશાવ્યવહારમાં સહાય કરવા માટેનું એક સાધન છે. તે કટોકટીમાં નિદાન, સારવાર યોજનાઓ નક્કી કરવા અથવા નિર્ણય લેવાનો હેતુ નથી. કટોકટીના કિસ્સામાં, કૃપા કરીને તબીબી કર્મચારીઓ અને કટોકટી સેવાઓની સૂચનાઓનું પાલન કરો.",
