    "s5.body": "אפליקציה זו אינה אוספת מידע אישי על השרת של המפתח, כך שהיא יכולה לשמש אנשים מכל הגילאים. עם זאת, אפליקציה זו נועדה לסייע לתקשורת במסגרות רפואיות ובביקור רופא, ואינה מיועדת בעיקר לילדים.",
    "s6.heading": "6. כיצד למחוק נתונים",
