    "s6.body2": "היסטוריית הרכישות עבור רכישות בתוך האפליקציה עבור גרסת iOS קשורה ל-Apple ID שלך ומאוחסנת בשרתי אפל, ותוכל להפעיל אותה מחדש על ידי לחיצה על \"שחזר רכישות\" בעת התקנה מחדש של האפליקציה. זה מנוהל על ידי אפל, לא האפליקציה.",
    "s7.heading": "7. הודעה לגבי מידע רפואי",
    "s7.body": "אפליקציה זו היא כלי המסייע לתקשורת טקסט עם אנשי מקצוע רפואיים. זה לא נועד לאבחן, לקבוע תוכניות טיפול או לשפוט במצבי חירום. במקרה חירום, אנא פעל לפי הנחיות הצוות הרפואי ושירותי החירום.",
    "s8.heading": "8. תיקון מדיניות",
    "s8.body": "מדיניות זו עשויה להשתנות לפי הצורך. אם יהיו שינויים חשובים, נודיע לך בדף זה.",
    "back": "← חזרה לדף התמיכה",
    "footer.copyright": "© 2026 Fumikazu Kondo. כֹּל הַזְכוּיוֹת שְׁמוּרוֹת.",
    "s2.android": "לגרסת האנדרואיד אין כרגע רכישות מתוך האפליקציה או תכונות מנוי.",
    "s3.body3": "גרסת האנדרואיד אינה מבצעת תקשורת עבור רכישות או מנויים בתוך האפליקציה. עם זאת, תקשורת עם Google או עם שירותי המערכת של המכשיר שלך עשויה להתרחש במקרים הבאים:",
