    "s6.heading": "6. Ki jan yo efase done",
    "s6.body1": "Si ou dezenstale aplikasyon sa a, done yo sove sou aparèy ou an (fraz modifye, favorites, anviwònman, elatriye) yo pral efase.",
    "s6.body2": "Istwa acha pou acha nan-app pou vèsyon iOS a mare ak Apple ID ou a epi li estoke sou sèvè Apple yo, epi ou ka reaktive li lè w klike sou \"Renstore Acha\" lè w re-enstale aplikasyon an. Sa a se jere pa Apple, pa app a.",
