    "s2.item6": "Kaupstaða innkaupa í forriti (Pro eiginleikar) í iOS útgáfu",
    "s3.heading": "3. Netsamskipti",
    "s3.body1": "Grunnsetningaskoðun þessa forrits, leit, flokkabirting, eftirlæti, flokkun og vistun breytts efnis starfar í tækinu.",
    "s3.body2": "iOS útgáfan hefur aðeins samskipti við netþjóna Apple (StoreKit) þegar keypt er í forriti eða endurheimt kaup. Þetta notar staðlaðan greiðsluvettvang sem Apple rekur og appið fangar engar greiðsluupplýsingar.",
    "s4.heading": "4. Upplýsingagjöf til þriðja aðila",
    "s4.body": "Þetta app safnar ekki persónulegum upplýsingum notenda, læknisfræðilegum upplýsingum eða sjúklingaupplýsingum á netþjóni þróunaraðilans, þannig að verktaki mun ekki veita þriðju aðilum þessar upplýsingar. Við notum heldur ekki bókasöfn þriðja aðila til auglýsinga, rakningar eða sérgreinagreiningar.",
    "s5.heading": "5. Notkun af börnum",
    "s5.body": "Þetta app safnar ekki persónulegum upplýsingum á netþjóni þróunaraðilans, svo fólk á öllum aldri getur notað það. Hins vegar er þessu forriti ætlað að aðstoða samskipti í læknisfræðilegum aðstæðum og þegar þú heimsækir lækni og er ekki hannað fyrst og fremst fyrir börn.",
    "s6.heading": "6. Hvernig á að eyða gögnum",
    "s6.body1": "Ef þú fjarlægir þetta forrit verður gögnum sem eru vistuð í tækinu þínu (breyttum orðasamböndum, uppáhaldi, stillingum osfrv.) eytt.",
    "s6.body2": "Kaupsaga fyrir innkaup í forriti fyrir iOS útgáfuna er bundinn við Apple ID og geymdur á netþjónum Apple og þú getur endurvirkjað hann með því að smella á \"Endurheimta kaup\" þegar þú setur forritið upp aftur. Þetta er stjórnað af Apple, ekki appinu.",
    "s7.heading": "7. Tilkynning um læknisfræðilegar upplýsingar",
    "s7.body": "Þetta app er tæki til að aðstoða textasamskipti við lækna. Það er ekki ætlað að greina, ákvarða meðferðaráætlanir eða dæma í neyðartilvikum. Í neyðartilvikum, vinsamlegast fylgdu leiðbeiningum sjúkraliða og neyðarþjónustu.",
    "s8.heading": "8. Endurskoðun stefnu",
    "s8.body": "Þessa stefnu má endurskoða eftir þörfum. Ef það eru einhverjar mikilvægar breytingar munum við láta þig vita á þessari síðu.",
    "back": "← Fara aftur á stuðningssíðu",
    "footer.copyright": "© 2026 Fumikazu Kondo. Allur réttur áskilinn.",
    "s2.android": "Android útgáfan er sem stendur ekki með kaup í forriti eða áskriftareiginleika.",
    "s3.body3": "Android útgáfan framkvæmir ekki samskipti fyrir kaup í forriti eða áskrift. Hins vegar geta samskipti við Google eða kerfisþjónustu tækisins átt sér stað í eftirfarandi tilvikum:",
    "s3.item1": "Hlaða niður eða undirbúið ML Kit þýðingarlíkan",
    "s3.item2": "Setningaleit með raddinnslætti",
    "s3.item3": "Samskipti fyrir greiningu og viðhald eindrægni með Android kerfi eða Google Play þjónustu",
    "s3.audio": "Raddinntak á Android útgáfunni er til að slá inn leitarorð með raddgreiningaraðgerð tækisins. Þetta app vistar ekki hljóðgögn.",
    "s4.body2": "Hins vegar geta SDK eins og Google ML Kit sem notað er í Android útgáfunni og raddþekkingarþjónustur á tækjum séð um tækisupplýsingar, forritaupplýsingar, villuupplýsingar, þýðingarstillingarmál o.s.frv. innan þess sviðs sem Google ákveður í tilgangi eins og niðurhali líkana, greiningu og gæðaviðhaldi. Þessar meðferðir eru háðar persónuverndarstefnu Google og forskriftum hverrar þjónustu.",
    "s6.android": "Android útgáfan er sem stendur ekki með kaup í forriti eða áskriftareiginleika.",
    "s9.heading": "9. Hafðu samband",
