    "s3.audio": "ხმოვანი შეყვანა Android-ის ვერსიაში არის საძიებო ტერმინების შეყვანისთვის მოწყობილობის ხმის ამოცნობის ფუნქციის გამოყენებით. ეს აპლიკაცია არ ინახავს აუდიო მონაცემებს.",
    "s4.body2": "თუმცა, SDK-ები, როგორიცაა Google ML Kit, რომელიც გამოიყენება Android ვერსიაში და ხმის ამოცნობის სერვისებში მოწყობილობებზე, შეიძლება ამუშავებდეს მოწყობილობის ინფორმაციას, აპლიკაციის ინფორმაციას, შეცდომის ინფორმაციას, თარგმანის პარამეტრების ენებს და ა.შ. Google-ის მიერ განსაზღვრული მიზნებისთვის, როგორიცაა მოდელის ჩამოტვირთვა, დიაგნოსტიკა და ხარისხის შენარჩუნება. ეს მკურნალობა ექვემდებარება Google-ის კონფიდენციალურობის პოლიტიკას და თითოეული სერვისის სპეციფიკაციებს.",
