    "env.item2": "ಮೂಲ ಕಾರ್ಯಗಳು ಟರ್ಮಿನಲ್ ಒಳಗೆ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತವೆ. ಅನುವಾದ ಮಾದರಿಯ ತಯಾರಿ ಮತ್ತು Android ಆವೃತ್ತಿಯಲ್ಲಿ ಧ್ವನಿ ಇನ್‌ಪುಟ್ ಸಮಯದಲ್ಲಿ ಸಂವಹನ ಸಂಭವಿಸಬಹುದು.",
