    "usage.item1": "ಮುಖಪುಟ ಪರದೆಯಲ್ಲಿ ಒಂದು ವರ್ಗವನ್ನು (ಸ್ವಾಗತ, ವೈದ್ಯಕೀಯ ಸಂದರ್ಶನ, ಪರೀಕ್ಷೆ, ಚಿಕಿತ್ಸೆ, ಇತ್ಯಾದಿ) ಟ್ಯಾಪ್ ಮಾಡಿ.",
    "usage.item2": "ಪ್ರದರ್ಶಿಸಲಾದ ಪದಗುಚ್ಛಗಳಿಂದ ನೀವು ತಿಳಿಸಲು ಬಯಸುವ ಪದಗುಚ್ಛವನ್ನು ನೀವು ಟ್ಯಾಪ್ ಮಾಡಿದರೆ, ಪರದೆಯನ್ನು ತುಂಬಲು ಅದನ್ನು ದೊಡ್ಡದಾಗಿ ಪ್ರದರ್ಶಿಸಲಾಗುತ್ತದೆ.",
    "usage.item3": "ಮೇಲಿನ ಬಲಭಾಗದಲ್ಲಿರುವ ಗೇರ್ ಐಕಾನ್‌ನಿಂದ ನೀವು ಭಾಷೆಗಳನ್ನು ಬದಲಾಯಿಸಬಹುದು (16 ಭಾಷೆಗಳು ಬೆಂಬಲಿತವಾಗಿದೆ).",
    "usage.item4": "ಅಗತ್ಯವಿದ್ದರೆ ಫ್ಯೂರಿಗಾನಾವನ್ನು ಪ್ರದರ್ಶಿಸಬಹುದು.",
    "pro.heading": "ಐಒಎಸ್ ಆವೃತ್ತಿ ಪ್ರೊ ವೈಶಿಷ್ಟ್ಯಗಳ ಬಗ್ಗೆ (ಒಂದು ಬಾರಿ ಖರೀದಿ)",
    "pro.item1": "ಮೆಚ್ಚಿನವುಗಳಿಗೆ ನುಡಿಗಟ್ಟುಗಳನ್ನು ಸೇರಿಸಿ ಮತ್ತು ಅವುಗಳನ್ನು ಮೇಲಕ್ಕೆ ಪಿನ್ ಮಾಡಿ",
    "pro.item2": "ವರ್ಗಗಳು ಮತ್ತು ಪದಗುಚ್ಛಗಳನ್ನು ಮುಕ್ತವಾಗಿ ಮರುಹೊಂದಿಸಿ",
    "pro.item3": "ಇದು ಐಒಎಸ್ ಆವೃತ್ತಿಯಲ್ಲಿ ಮಾತ್ರ ಲಭ್ಯವಿರುವ ವೈಶಿಷ್ಟ್ಯವಾಗಿದೆ. Android ಆವೃತ್ತಿಯು ಪ್ರಸ್ತುತ ಅಪ್ಲಿಕೇಶನ್‌ನಲ್ಲಿನ ಖರೀದಿಗಳು ಅಥವಾ ಚಂದಾದಾರಿಕೆ ವೈಶಿಷ್ಟ್ಯಗಳನ್ನು ಹೊಂದಿಲ್ಲ.",
    "restore.heading": "iOS ನಲ್ಲಿ ಖರೀದಿಗಳನ್ನು ಮರುಸ್ಥಾಪಿಸಲು",
