    "restore.item2": "ಖರೀದಿಗಳನ್ನು ಮರುಸ್ಥಾಪಿಸಿ ಟ್ಯಾಪ್ ಮಾಡಿ.",
    "restore.item3": "ನಿಮ್ಮ Apple ID ಗೆ ನೀವು ಸೈನ್ ಇನ್ ಆಗಿದ್ದರೆ, ನಿಮ್ಮ ಖರೀದಿ ಇತಿಹಾಸದಿಂದ Pro ವೈಶಿಷ್ಟ್ಯಗಳನ್ನು ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಮರು-ಸಕ್ರಿಯಗೊಳಿಸಲಾಗುತ್ತದೆ.",
    "restore.note": "ಮಾದರಿಗಳನ್ನು ಬದಲಾಯಿಸುವಾಗ ಅಥವಾ ಮರುಸ್ಥಾಪಿಸುವಾಗಲೂ ನೀವು ಈ ವಿಧಾನವನ್ನು ಬಳಸಿಕೊಂಡು ಮರುಸ್ಥಾಪಿಸಬಹುದು. Android ಆವೃತ್ತಿಯು ಖರೀದಿ ಮರುಸ್ಥಾಪನೆ ಐಟಂಗಳನ್ನು ಹೊಂದಿಲ್ಲ.",
    "faq.heading": "ಪದೇ ಪದೇ ಕೇಳಲಾಗುವ ಪ್ರಶ್ನೆಗಳು",
    "faq.q1": "ಪ್ರ. ಯಾವುದೇ ಸಂವಹನ ಇರುತ್ತದೆಯೇ?",
    "faq.a1": "A. ಮೂಲಭೂತ ಕಾರ್ಯಚಟುವಟಿಕೆಯು ಟರ್ಮಿನಲ್‌ನಲ್ಲಿ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತದೆ. iOS ಆವೃತ್ತಿಯಲ್ಲಿ ಅಪ್ಲಿಕೇಶನ್‌ನಲ್ಲಿ ಖರೀದಿಗಳನ್ನು ಮಾಡುವಾಗ, ಅದು Apple ನ ಸರ್ವರ್‌ಗಳೊಂದಿಗೆ ಸಂವಹನ ನಡೆಸುತ್ತದೆ. ಅನುವಾದ ಮಾದರಿಯನ್ನು ಸಿದ್ಧಪಡಿಸುವಾಗ ಅಥವಾ Android ಆವೃತ್ತಿಯಲ್ಲಿ ಧ್ವನಿ ಇನ್‌ಪುಟ್ ಬಳಸುವಾಗ, Google ಅಥವಾ ಸಾಧನದ ಸಿಸ್ಟಮ್ ಸೇವೆಗಳೊಂದಿಗೆ ಸಂವಹನ ಸಂಭವಿಸಬಹುದು.",
    "faq.q2": "ಪ್ರ. ನೀವು ರೋಗಿಗಳ ಮಾಹಿತಿಯನ್ನು ಸಂಗ್ರಹಿಸುತ್ತೀರಾ?",
    "faq.a2": "ಎ. ನಾವು ಏನನ್ನೂ ಉಳಿಸುವುದಿಲ್ಲ. ಆಯ್ದ ಭಾಷೆ, ಡಿಸ್‌ಪ್ಲೇ ಸೆಟ್ಟಿಂಗ್‌ಗಳು, ಪದಗುಚ್ಛ ಸಂಪಾದನೆಗಳು, ಮೆಚ್ಚಿನವುಗಳು, ವಿಂಗಡಣೆಯ ಕ್ರಮ ಮತ್ತು iOS ಖರೀದಿ ಸ್ಥಿತಿ ಮಾತ್ರ ಅಪ್ಲಿಕೇಶನ್‌ನಲ್ಲಿ ಉಳಿಸಲಾಗಿದೆ ಮತ್ತು ಇವುಗಳನ್ನು ಸಾಧನದಲ್ಲಿ ಉಳಿಸಲಾಗುತ್ತದೆ.",
    "faq.q3": "ಪ್ರ. 16 ಭಾಷೆಗಳನ್ನು ಹೇಗೆ ಅನುವಾದಿಸಲಾಗಿದೆ?",
    "faq.a3": "ಎ. ಬಿಡುಗಡೆಯ ಮೊದಲು ಪ್ರತಿ ಭಾಷೆಯಲ್ಲಿನ ಅಭಿವ್ಯಕ್ತಿಗಳನ್ನು ಪರಿಶೀಲಿಸಿದ ನಂತರ ಪ್ರಮಾಣಿತ ನುಡಿಗಟ್ಟುಗಳನ್ನು ದಾಖಲಿಸಲಾಗುತ್ತದೆ. ಅಪ್ಲಿಕೇಶನ್‌ನಲ್ಲಿ ಬಾಹ್ಯ ಅನುವಾದ API ಗಳಿಗೆ ಯಾವುದೇ ಪ್ರವೇಶವಿಲ್ಲ.",
    "contact.heading": "ವಿಚಾರಣೆ",
    "contact.body": "ನೀವು ದೋಷವನ್ನು ವರದಿ ಮಾಡಲು, ವೈಶಿಷ್ಟ್ಯವನ್ನು ವಿನಂತಿಸಲು ಅಥವಾ ಯಾವುದೇ ಇತರ ವಿಚಾರಣೆಗಳನ್ನು ಹೊಂದಿದ್ದರೆ, ದಯವಿಟ್ಟು ಕೆಳಗೆ ನಮ್ಮನ್ನು ಸಂಪರ್ಕಿಸಿ.",
    "privacy.heading": "ಗೌಪ್ಯತೆ ನೀತಿ",
    "privacy.body.before": "ಈ ಅಪ್ಲಿಕೇಶನ್‌ನ ಗೌಪ್ಯತೆ ನೀತಿ",
    "privacy.link": "ಇಲ್ಲಿ",
