    "s2.item3": "ಪೂರ್ವ-ರೆಕಾರ್ಡ್ ಮಾಡಿದ ವೈದ್ಯಕೀಯ ನುಡಿಗಟ್ಟುಗಳು ಮತ್ತು ಬಳಕೆದಾರ-ಸಂಪಾದಿತ/ಸೇರಿಸಿದ ನುಡಿಗಟ್ಟುಗಳು",
    "s2.item4": "ಅದನ್ನು ಮೆಚ್ಚಿನವು ಎಂದು ನೋಂದಾಯಿಸಲಾಗಿದೆಯೇ ಅಥವಾ ಇಲ್ಲವೇ ಮತ್ತು ಅದನ್ನು ಮೆಚ್ಚಿನ ಕ್ರಮದಲ್ಲಿ ಪಟ್ಟಿಮಾಡಲಾಗಿದೆ",
    "s2.item5": "ವರ್ಗಗಳು ಮತ್ತು ಪದಗುಚ್ಛಗಳ ಕ್ರಮವನ್ನು ವಿಂಗಡಿಸಿ",
    "s2.item6": "iOS ಆವೃತ್ತಿಯಲ್ಲಿ ಅಪ್ಲಿಕೇಶನ್‌ನಲ್ಲಿನ ಖರೀದಿಗಳ (ಪ್ರೊ ವೈಶಿಷ್ಟ್ಯಗಳು) ಖರೀದಿ ಸ್ಥಿತಿ",
    "s3.heading": "3. ನೆಟ್ವರ್ಕ್ ಸಂವಹನ",
    "s3.body1": "ಈ ಅಪ್ಲಿಕೇಶನ್‌ನ ಮೂಲ ನುಡಿಗಟ್ಟು ವೀಕ್ಷಣೆ, ಹುಡುಕಾಟ, ವರ್ಗದ ಪ್ರದರ್ಶನ, ಮೆಚ್ಚಿನವುಗಳು, ವಿಂಗಡಣೆ ಮತ್ತು ಸಂಪಾದಿತ ವಿಷಯವನ್ನು ಉಳಿಸುವುದು ಸಾಧನದಲ್ಲಿ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತದೆ.",
    "s3.body2": "ಅಪ್ಲಿಕೇಶನ್‌ನಲ್ಲಿನ ಖರೀದಿಗಳನ್ನು ಖರೀದಿಸುವಾಗ ಅಥವಾ ಖರೀದಿಗಳನ್ನು ಮರುಸ್ಥಾಪಿಸುವಾಗ iOS ಆವೃತ್ತಿಯು Apple ನ ಸರ್ವರ್‌ಗಳೊಂದಿಗೆ (StoreKit) ಮಾತ್ರ ಸಂವಹನ ನಡೆಸುತ್ತದೆ. ಇದು Apple ನಿಂದ ನಿರ್ವಹಿಸಲ್ಪಡುವ ಪ್ರಮಾಣಿತ ಪಾವತಿ ವೇದಿಕೆಯನ್ನು ಬಳಸುತ್ತದೆ ಮತ್ತು ಅಪ್ಲಿಕೇಶನ್ ಯಾವುದೇ ಪಾವತಿ ಮಾಹಿತಿಯನ್ನು ಸೆರೆಹಿಡಿಯುವುದಿಲ್ಲ.",
    "s4.heading": "4. ಮೂರನೇ ವ್ಯಕ್ತಿಗಳಿಗೆ ಮಾಹಿತಿಯನ್ನು ಒದಗಿಸುವುದು",
    "s4.body": "ಈ ಅಪ್ಲಿಕೇಶನ್ ಬಳಕೆದಾರರ ವೈಯಕ್ತಿಕ ಮಾಹಿತಿ, ವೈದ್ಯಕೀಯ ಮಾಹಿತಿ ಅಥವಾ ಡೆವಲಪರ್ ಸರ್ವರ್‌ನಲ್ಲಿ ರೋಗಿಯ ಮಾಹಿತಿಯನ್ನು ಸಂಗ್ರಹಿಸುವುದಿಲ್ಲ, ಆದ್ದರಿಂದ ಡೆವಲಪರ್ ಈ ಮಾಹಿತಿಯನ್ನು ಮೂರನೇ ವ್ಯಕ್ತಿಗಳಿಗೆ ಒದಗಿಸುವುದಿಲ್ಲ. ಜಾಹೀರಾತು, ಟ್ರ್ಯಾಕಿಂಗ್ ಅಥವಾ ಸ್ವಾಮ್ಯದ ವಿಶ್ಲೇಷಣೆಗಾಗಿ ನಾವು ಮೂರನೇ ವ್ಯಕ್ತಿಯ ಲೈಬ್ರರಿಗಳನ್ನು ಸಹ ಬಳಸುವುದಿಲ್ಲ.",
    "s5.heading": "5. ಮಕ್ಕಳಿಂದ ಬಳಸಿ",
    "s5.body": "ಈ ಅಪ್ಲಿಕೇಶನ್ ಡೆವಲಪರ್‌ಗಳ ಸರ್ವರ್‌ನಲ್ಲಿ ವೈಯಕ್ತಿಕ ಮಾಹಿತಿಯನ್ನು ಸಂಗ್ರಹಿಸುವುದಿಲ್ಲ, ಆದ್ದರಿಂದ ಇದನ್ನು ಎಲ್ಲಾ ವಯಸ್ಸಿನ ಜನರು ಬಳಸಬಹುದು. ಆದಾಗ್ಯೂ, ಈ ಅಪ್ಲಿಕೇಶನ್ ವೈದ್ಯಕೀಯ ಸೆಟ್ಟಿಂಗ್‌ಗಳಲ್ಲಿ ಮತ್ತು ವೈದ್ಯರನ್ನು ಭೇಟಿ ಮಾಡುವಾಗ ಸಂವಹನಕ್ಕೆ ಸಹಾಯ ಮಾಡುವ ಉದ್ದೇಶವನ್ನು ಹೊಂದಿದೆ ಮತ್ತು ಇದನ್ನು ಪ್ರಾಥಮಿಕವಾಗಿ ಮಕ್ಕಳಿಗಾಗಿ ವಿನ್ಯಾಸಗೊಳಿಸಲಾಗಿಲ್ಲ.",
    "s6.heading": "6. ಡೇಟಾವನ್ನು ಅಳಿಸುವುದು ಹೇಗೆ",
    "s6.body1": "ನೀವು ಈ ಅಪ್ಲಿಕೇಶನ್ ಅನ್ನು ಅನ್‌ಇನ್‌ಸ್ಟಾಲ್ ಮಾಡಿದರೆ, ನಿಮ್ಮ ಸಾಧನದಲ್ಲಿ ಉಳಿಸಲಾದ ಡೇಟಾವನ್ನು (ಸಂಪಾದಿಸಿದ ನುಡಿಗಟ್ಟುಗಳು, ಮೆಚ್ಚಿನವುಗಳು, ಸೆಟ್ಟಿಂಗ್‌ಗಳು, ಇತ್ಯಾದಿ) ಅಳಿಸಲಾಗುತ್ತದೆ.",
    "s6.body2": "iOS ಆವೃತ್ತಿಗಾಗಿ ಅಪ್ಲಿಕೇಶನ್‌ನಲ್ಲಿನ ಖರೀದಿಗಳ ಖರೀದಿ ಇತಿಹಾಸವನ್ನು ನಿಮ್ಮ Apple ID ಗೆ ಜೋಡಿಸಲಾಗಿದೆ ಮತ್ತು Apple ನ ಸರ್ವರ್‌ಗಳಲ್ಲಿ ಸಂಗ್ರಹಿಸಲಾಗಿದೆ ಮತ್ತು ಅಪ್ಲಿಕೇಶನ್ ಅನ್ನು ಮರುಸ್ಥಾಪಿಸುವಾಗ \"ಖರೀದಿಗಳನ್ನು ಮರುಸ್ಥಾಪಿಸು\" ಕ್ಲಿಕ್ ಮಾಡುವ ಮೂಲಕ ನೀವು ಅದನ್ನು ಮರುಸಕ್ರಿಯಗೊಳಿಸಬಹುದು. ಇದನ್ನು ಆಪಲ್ ನಿರ್ವಹಿಸುತ್ತದೆ, ಅಪ್ಲಿಕೇಶನ್ ಅಲ್ಲ.",
    "s7.heading": "7. ವೈದ್ಯಕೀಯ ಮಾಹಿತಿಗೆ ಸಂಬಂಧಿಸಿದಂತೆ ಸೂಚನೆ",
    "s7.body": "ಈ ಅಪ್ಲಿಕೇಶನ್ ವೈದ್ಯಕೀಯ ವೃತ್ತಿಪರರೊಂದಿಗೆ ಪಠ್ಯ ಸಂವಹನಕ್ಕೆ ಸಹಾಯ ಮಾಡುವ ಸಾಧನವಾಗಿದೆ. ಇದು ರೋಗನಿರ್ಣಯ ಮಾಡಲು, ಚಿಕಿತ್ಸೆಯ ಯೋಜನೆಗಳನ್ನು ನಿರ್ಧರಿಸಲು ಅಥವಾ ತುರ್ತು ಸಂದರ್ಭಗಳಲ್ಲಿ ತೀರ್ಪುಗಳನ್ನು ಮಾಡಲು ಉದ್ದೇಶಿಸಿಲ್ಲ. ತುರ್ತು ಸಂದರ್ಭದಲ್ಲಿ, ದಯವಿಟ್ಟು ವೈದ್ಯಕೀಯ ಸಿಬ್ಬಂದಿ ಮತ್ತು ತುರ್ತು ಸೇವೆಗಳ ಸೂಚನೆಗಳನ್ನು ಅನುಸರಿಸಿ.",
    "s8.heading": "8. ನೀತಿ ಪರಿಷ್ಕರಣೆ",
    "s8.body": "ಅಗತ್ಯವಿರುವಂತೆ ಈ ನೀತಿಯನ್ನು ಪರಿಷ್ಕರಿಸಬಹುದು. ಯಾವುದೇ ಪ್ರಮುಖ ಬದಲಾವಣೆಗಳಿದ್ದರೆ, ನಾವು ಈ ಪುಟದಲ್ಲಿ ನಿಮಗೆ ತಿಳಿಸುತ್ತೇವೆ.",
    "back": "← ಬೆಂಬಲ ಪುಟಕ್ಕೆ ಹಿಂತಿರುಗಿ",
