    "s2.android": "Android ಆವೃತ್ತಿಯು ಪ್ರಸ್ತುತ ಅಪ್ಲಿಕೇಶನ್‌ನಲ್ಲಿನ ಖರೀದಿಗಳು ಅಥವಾ ಚಂದಾದಾರಿಕೆ ವೈಶಿಷ್ಟ್ಯಗಳನ್ನು ಹೊಂದಿಲ್ಲ.",
