    "s3.item3": "Android ಸಿಸ್ಟಮ್ ಅಥವಾ Google Play ಸೇವೆಗಳಿಂದ ರೋಗನಿರ್ಣಯ ಮತ್ತು ಹೊಂದಾಣಿಕೆ ನಿರ್ವಹಣೆಗಾಗಿ ಸಂವಹನ",
    "s3.audio": "Android ಆವೃತ್ತಿಯಲ್ಲಿನ ಧ್ವನಿ ಇನ್‌ಪುಟ್ ಸಾಧನದ ಧ್ವನಿ ಗುರುತಿಸುವಿಕೆ ಕಾರ್ಯವನ್ನು ಬಳಸಿಕೊಂಡು ಹುಡುಕಾಟ ಪದಗಳನ್ನು ಇನ್‌ಪುಟ್ ಮಾಡಲು ಆಗಿದೆ. ಈ ಅಪ್ಲಿಕೇಶನ್ ಆಡಿಯೊ ಡೇಟಾವನ್ನು ಉಳಿಸುವುದಿಲ್ಲ.",
