    "s4.body": "Оваа апликација не ги собира личните информации на корисниците, медицинските информации или информациите за пациентот на серверот на развивачот, така што развивачот нема да ги дава овие информации на трети страни. Ние, исто така, не користиме библиотеки од трета страна за рекламирање, следење или комерцијална аналитика.",
    "s5.heading": "5. Употреба од деца",
    "s5.body": "Оваа апликација не собира лични информации на серверот на развивачот, така што може да ја користат луѓе од сите возрасти. Сепак, оваа апликација е наменета да помогне во комуникацијата во медицинските услови и при посета на лекар и не е наменета првенствено за деца.",
    "s6.heading": "6. Како да избришете податоци",
    "s6.body1": "Ако ја деинсталирате оваа апликација, податоците зачувани на вашиот уред (уредени фрази, омилени, поставки итн.) ќе бидат избришани.",
    "s6.body2": "Историјата на набавки за купувања во апликација за верзијата на iOS е поврзана со вашиот Apple ID и се складира на серверите на Apple, а можете повторно да ја активирате со кликнување на „Врати купувања“ при повторно инсталирање на апликацијата. Ова го управува Apple, а не апликацијата.",
    "s7.heading": "7. Известување за медицински информации",
    "s7.body": "Оваа апликација е алатка за помош на текстуална комуникација со медицински професионалци. Не е наменет за дијагностицирање, одредување планови за лекување или донесување судови во итни случаи. Во случај на итен случај, ве молиме следете ги упатствата на медицинскиот персонал и итните служби.",
    "s8.heading": "8. Ревизија на политиката",
    "s8.body": "Оваа политика може да се ревидира доколку е потребно. Доколку има некои важни промени, ќе ве известиме на оваа страница.",
    "back": "← Вратете се на страницата за поддршка",
    "footer.copyright": "© 2026 Фумиказу Кондо. Сите права се задржани.",
    "s2.android": "Верзијата на Android во моментов нема купувања во апликација или функции за претплата.",
    "s3.body3": "Верзијата на Android не врши комуникација за купувања или претплати во апликација. Меѓутоа, комуникацијата со Google или системските услуги на вашиот уред може да се случи во следниве случаи:",
    "s3.item1": "Преземете или подгответе модел за превод на ML Kit",
    "s3.item2": "Пребарување фрази со гласовен внес",
    "s3.item3": "Комуникација за дијагностика и одржување на компатибилност преку системот Android или услугите на Google Play",
    "s3.audio": "Гласовното внесување на верзијата на Android е за внесување термини за пребарување користејќи ја функцијата за препознавање глас на уредот. Оваа апликација не зачувува аудио податоци.",
    "s4.body2": "Сепак, SDK-ите како што е Google ML Kit што се користат во верзијата на Android и услугите за препознавање глас на уредите може да ракуваат со информации за уредот, информации за апликацијата, информации за грешки, јазици за поставки за превод итн. во опсегот што го одредува Google за цели како што се преземање модел, дијагноза и квалитетно одржување. Овие третмани се предмет на политиката за приватност на Google и спецификациите на секоја услуга.",
    "s6.android": "Верзијата на Android во моментов нема купувања во апликација или функции за претплата.",
    "s9.heading": "9. Контактирајте не",
