    "s4.body2": "तथापि, SDKs जसे की Android आवृत्तीमध्ये वापरलेले Google ML किट आणि डिव्हाइसेसवरील व्हॉइस रेकग्निशन सेवा हे मॉडेल डाउनलोड, निदान आणि गुणवत्ता देखभाल यासारख्या उद्देशांसाठी Google ने निर्धारित केलेल्या कार्यक्षेत्रात डिव्हाइस माहिती, अनुप्रयोग माहिती, त्रुटी माहिती, भाषांतर सेटिंग भाषा इत्यादी हाताळू शकतात. हे उपचार Google च्या गोपनीयता धोरण आणि प्रत्येक सेवेच्या वैशिष्ट्यांच्या अधीन आहेत.",
