    "header.subtitle": "Ziekenhuis-/noodgevallenbord",
    "header.updated": "Datum voor het laatst bijgewerkt",
    "header.date": "20 mei 2026",
    "intro": "Fumikazu Kondo (hierna te noemen de ``Ontwikkelaar'') acht de privacybescherming van gebruikers van de iOS- en Android-versie van de app ``Hospital/Emergency Waku-kun Board'' (hierna te noemen de ``App'') uiterst belangrijk. In dit beleid wordt uitgelegd hoe informatie door deze app wordt verwerkt.",
    "s1.heading": "1. Te verkrijgen informatie",
    "s1.body": "<strong>Deze app verzamelt of verzendt geen informatie die individuele gebruikers kan identificeren, gebruiksstatistieken, medische informatie of patiëntinformatie naar de server van de ontwikkelaar.</strong>",
    "s2.heading": "2. Informatie opgeslagen op uw apparaat",
    "s2.body": "Deze applicatie slaat de volgende informatie op het apparaat van de gebruiker op. Deze worden nooit naar de servers van de ontwikkelaar verzonden.",
