    "s2.item6": "Aankoopstatus van in-app-aankopen (Pro-functies) in iOS-versie",
    "s3.heading": "3. Netwerkcommunicatie",
    "s3.body1": "De basisfuncties voor het bekijken, zoeken, weergeven van categorieën, favorieten, sorteren en opslaan van bewerkte inhoud van deze app werken op het apparaat.",
    "s3.body2": "De iOS-versie communiceert alleen met de servers van Apple (StoreKit) bij het kopen van in-app-aankopen of het herstellen van aankopen. Hierbij wordt gebruik gemaakt van het standaard betalingsplatform van Apple, en de app legt geen betalingsinformatie vast.",
    "s4.heading": "4. Verstrekken van informatie aan derden",
    "s4.body": "Deze app verzamelt geen persoonlijke informatie van gebruikers, medische informatie of patiëntinformatie op de server van de ontwikkelaar, dus de ontwikkelaar zal deze informatie niet aan derden verstrekken. We gebruiken ook geen bibliotheken van derden voor advertenties, tracking of eigen analyses.",
    "s5.heading": "5. Gebruik door kinderen",
    "s5.body": "Deze app verzamelt geen persoonlijke informatie op de server van de ontwikkelaar en kan dus door mensen van alle leeftijden worden gebruikt. Deze app is echter bedoeld om de communicatie in medische omgevingen en bij een bezoek aan een arts te ondersteunen, en is niet in de eerste plaats bedoeld voor kinderen.",
    "s6.heading": "6. Gegevens verwijderen",
    "s6.body1": "Als u deze app verwijdert, worden de gegevens die op uw apparaat zijn opgeslagen (bewerkte zinnen, favorieten, instellingen, enz.) verwijderd.",
    "s6.body2": "De aankoopgeschiedenis voor in-app-aankopen voor de iOS-versie is gekoppeld aan uw Apple ID en opgeslagen op de servers van Apple. U kunt deze opnieuw activeren door op 'Aankopen herstellen' te klikken wanneer u de app opnieuw installeert. Dit wordt beheerd door Apple, niet door de app.",
    "s7.heading": "7. Kennisgeving met betrekking tot medische informatie",
    "s7.body": "Deze app is een hulpmiddel om tekstcommunicatie met medische professionals te ondersteunen. Het is niet bedoeld om in noodsituaties een diagnose te stellen, behandelplannen vast te stellen of een oordeel te vellen. In geval van nood dient u de instructies van het medisch personeel en de hulpdiensten op te volgen.",
    "s8.heading": "8. Beleidsherziening",
    "s8.body": "Dit beleid kan indien nodig worden herzien. Mochten er belangrijke wijzigingen plaatsvinden, dan zullen wij u hiervan op deze pagina op de hoogte stellen.",
    "back": "← Terug naar de ondersteuningspagina",
    "footer.copyright": "© 2026 Fumikazu Kondo. Alle rechten voorbehouden.",
    "s2.android": "De Android-versie heeft momenteel geen in-app-aankopen of abonnementsfuncties.",
    "s3.body3": "De Android-versie voert geen communicatie uit voor in-app-aankopen of abonnementen. In de volgende gevallen kan er echter communicatie plaatsvinden met Google of de systeemservices van uw apparaat:",
    "s3.item1": "Download of bereid een ML Kit-vertaalmodel voor",
    "s3.item2": "Zin zoeken via spraakinvoer",
    "s3.item3": "Communicatie voor diagnose en compatibiliteitsonderhoud door Android-systeem of Google Play-services",
    "s3.audio": "Spraakinvoer op de Android-versie is voor het invoeren van zoektermen met behulp van de spraakherkenningsfunctie van het apparaat. Deze app slaat geen audiogegevens op.",
    "s4.body2": "SDK's zoals Google ML Kit die in de Android-versie worden gebruikt en spraakherkenningsservices op apparaten kunnen echter apparaatinformatie, applicatie-informatie, foutinformatie, talen voor vertaalinstellingen, enz. verwerken binnen de door Google bepaalde reikwijdte voor doeleinden zoals het downloaden van modellen, diagnose en kwaliteitsonderhoud. Op deze behandelingen zijn het privacybeleid van Google en de specificaties van elke dienst van toepassing.",
    "s6.android": "De Android-versie heeft momenteel geen in-app-aankopen of abonnementsfuncties.",
    "s9.heading": "9. Neem contact met ons op",
    "s9.body": "Voor vragen over dit beleid of de omgang met informatie in deze app kunt u hieronder contact met ons opnemen."
