    "header.updated": "Sist oppdatert dato",
    "header.date": "20. mai 2026",
    "intro": "Fumikazu Kondo (heretter referert til som ``Utvikleren'') anser personvernet til brukere av iOS- og Android-versjonen av appen ``Hospital/Emergency Waku-kun Board'' (heretter referert til som ``App'') som ekstremt viktig. Denne policyen forklarer hvordan informasjon håndteres av denne appen.",
    "s1.heading": "1. Informasjon som skal innhentes",
