    "s5.body": "Denne appen samler ikke inn personlig informasjon på utviklerens server, så den kan brukes av folk i alle aldre. Denne appen er imidlertid ment å hjelpe til med kommunikasjon i medisinske omgivelser og ved legebesøk, og er ikke designet primært for barn.",
