    "header.date": "20 мая 2026 г.",
    "intro": "Фумиказу Кондо (именуемый в дальнейшем «Разработчик») считает, что защита конфиденциальности пользователей версии iOS и Android приложения «Hospital/Emergency Waku-kun Board» (далее именуемого «Приложение») чрезвычайно важна. Эта политика объясняет, как данное приложение обрабатывает информацию.",
    "s1.heading": "1. Информация, которую необходимо получить",
    "s1.body": "<strong>Это приложение не собирает и не отправляет на сервер разработчика информацию, позволяющую идентифицировать отдельных пользователей, статистику использования, медицинскую информацию или информацию о пациентах.</strong>",
