    "s2.body": "Это приложение сохраняет следующую информацию на устройстве пользователя. Они никогда не отправляются на серверы разработчика.",
    "s2.item1": "Выбранный язык отображения",
    "s2.item2": "Настройки дисплея, такие как отображение фуриганы.",
    "s2.item3": "Предварительно записанные медицинские фразы и фразы, отредактированные/добавленные пользователем.",
