    "s2.item5": "Порядок сортировки категорий и фраз",
    "s2.item6": "Статус покупки в приложении (функции Pro) в версии iOS",
    "s3.heading": "3. Сетевое общение",
    "s3.body1": "Основные функции просмотра фраз, поиска, отображения категорий, избранного, сортировки и сохранения отредактированного контента в этом приложении выполняются на устройстве.",
    "s3.body2": "Версия iOS взаимодействует с серверами Apple (StoreKit) только при покупке покупок в приложении или восстановлении покупок. При этом используется стандартная платежная платформа Apple, и приложение не собирает никакой платежной информации.",
    "s4.heading": "4. Предоставление информации третьим лицам",
    "s4.body": "Это приложение не собирает личную информацию пользователей, медицинскую информацию или информацию о пациентах на сервере разработчика, поэтому разработчик не будет предоставлять эту информацию третьим лицам. Мы также не используем сторонние библиотеки для рекламы, отслеживания или собственной аналитики.",
    "s5.heading": "5. Использование детьми",
    "s5.body": "Это приложение не собирает личную информацию на сервере разработчика, поэтому его могут использовать люди всех возрастов. Однако это приложение предназначено для облегчения общения в медицинских учреждениях и при посещении врача и не предназначено в первую очередь для детей.",
    "s6.heading": "6. Как удалить данные",
    "s6.body1": "Если вы удалите это приложение, данные, сохраненные на вашем устройстве (отредактированные фразы, избранное, настройки и т. д.), будут удалены.",
    "s6.body2": "История покупок в приложении для версии iOS привязана к вашему Apple ID и хранится на серверах Apple, и вы можете повторно активировать ее, нажав «Восстановить покупки» при переустановке приложения. Этим управляет Apple, а не приложение.",
    "s7.heading": "7. Уведомление о медицинской информации",
    "s7.body": "Это приложение представляет собой инструмент для текстового общения с медицинскими работниками. Он не предназначен для диагностики, определения планов лечения или вынесения суждений в чрезвычайных ситуациях. В случае возникновения чрезвычайной ситуации следуйте инструкциям медицинского персонала и служб экстренной помощи.",
    "s8.heading": "8. Пересмотр политики",
    "s8.body": "Эта политика может быть пересмотрена по мере необходимости. Если произойдут какие-либо важные изменения, мы сообщим вам на этой странице.",
    "back": "← Вернуться на страницу поддержки",
    "footer.copyright": "© 2026 Фумиказу Кондо. Все права защищены.",
    "s2.android": "Версия для Android в настоящее время не поддерживает встроенные покупки и функции подписки.",
    "s3.body3": "Версия Android не поддерживает связь для покупок или подписок в приложении. Однако связь с Google или системными службами вашего устройства может возникнуть в следующих случаях:",
