    "s3.audio": "Голосовой ввод в версии Android предназначен для ввода условий поиска с помощью функции распознавания голоса устройства. Это приложение не сохраняет аудиоданные.",
    "s4.body2": "Однако SDK, такие как Google ML Kit, используемые в версии Android и службах распознавания голоса на устройствах, могут обрабатывать информацию об устройстве, информацию о приложении, информацию об ошибках, языки настройки перевода и т. д. в объеме, определенном Google для таких целей, как загрузка модели, диагностика и поддержание качества. Эти процедуры регулируются политикой конфиденциальности Google и спецификациями каждой службы.",
    "s6.android": "Версия для Android в настоящее время не поддерживает встроенные покупки и функции подписки.",
    "s9.heading": "9. Свяжитесь с нами",
