    "intro": "Fumikazu Kondo (hädanefter kallad ``Utvecklaren'') anser att integritetsskyddet för användare av iOS- och Android-versionen av appen ``Hospital/Emergency Waku-kun Board'' (hädanefter kallat ``App'') är extremt viktigt. Denna policy förklarar hur information hanteras av den här appen.",
