    "s4.body": "Denna app samlar inte in användarnas personliga information, medicinsk information eller patientinformation på utvecklarens server, så utvecklaren kommer inte att tillhandahålla denna information till tredje part. Vi använder inte heller tredjepartsbibliotek för reklam, spårning eller proprietär analys.",
    "s5.heading": "5. Används av barn",
    "s5.body": "Den här appen samlar inte in personlig information på utvecklarens server, så den kan användas av människor i alla åldrar. Den här appen är dock avsedd att underlätta kommunikation i medicinska miljöer och vid läkarbesök, och är inte avsedd främst för barn.",
