    "s3.body2": "Версія iOS спілкується лише з серверами Apple (StoreKit) під час здійснення покупок у додатку або відновлення покупок. Для цього використовується стандартна платіжна платформа Apple, і програма не збирає платіжну інформацію.",
    "s4.heading": "4. Надання інформації третім особам",
    "s4.body": "Ця програма не збирає особисту інформацію користувачів, медичну інформацію чи інформацію про пацієнтів на сервері розробника, тому розробник не надаватиме цю інформацію третім особам. Ми також не використовуємо бібліотеки третіх сторін для реклами, відстеження або власної аналітики.",
