    "s7.body": "Ця програма є інструментом для текстового спілкування з медичними працівниками. Він не призначений для діагностики, визначення планів лікування або прийняття рішень у надзвичайних ситуаціях. У разі надзвичайної ситуації дотримуйтеся вказівок медичного персоналу та екстрених служб.",
    "s8.heading": "8. Перегляд політики",
    "s8.body": "Ця політика може бути переглянута за необхідності. Якщо будуть важливі зміни, ми повідомимо вас на цій сторінці.",
