    "footer.copyright": "© 2026 Fumikazu Kondo. Всі права захищені.",
    "s2.android": "Версія для Android наразі не має функцій покупок у додатку чи підписки.",
    "s3.body3": "Версія Android не підтримує зв’язок для покупок у програмі чи підписок. Однак зв’язок із Google або системними службами вашого пристрою може відбуватися в таких випадках:",
    "s3.item1": "Завантажте або підготуйте модель перекладу ML Kit",
