    "s4.body2": "Однак пакети SDK, такі як Google ML Kit, які використовуються у версії Android, і служби розпізнавання голосу на пристроях можуть обробляти інформацію про пристрій, інформацію про програму, інформацію про помилки, мови налаштування перекладу тощо в межах, визначених Google для таких цілей, як завантаження моделі, діагностика та підтримка якості. Ці дії регулюються політикою конфіденційності Google і специфікаціями кожної служби.",
