    "restore.item3": "如果你登入咗你嘅 Apple ID ， Pro 功能就會喺你嘅購買記錄入面自動重新啟用。",
    "restore.note": "即使係改型號或者重新安裝嗰陣，你都可以用呢個程序還原。 Android 版本冇購買還原項目。",
    "faq.heading": "常見問題",
    "faq.q1": "問：會唔會有任何溝通？",
    "faq.a1": "A. 基本功能係喺終端入面運作。喺 iOS 版本上面進行應用程式內購買嗰陣，佢會同 Apple 嘅伺服器通訊。喺 Android 版本上面準備翻譯模型或者用語音輸入嗰陣，可能會同 Google 或者裝置嘅系統服務發生通訊。",
    "faq.q2": "問：你會唔會儲存病人資料？",
    "faq.a2": "A. 我哋乜都唔會慳。喺應用程式入面唯一儲存嘅內容係所選語言、顯示設定、詞組編輯、收藏、排序順序同埋 iOS 購買狀態，而呢啲內容會儲存喺裝置上面。",
    "faq.q3": "問：16種語言係點樣翻譯嘅？",
    "faq.a3": "A. 標準短語係喺發佈前檢查每種語言嘅表達方式之後先記錄。喺應用程式入面唔可以存取外部翻譯 API 。",
    "contact.heading": "詢問",
    "contact.body": "如果你想報告錯誤、要求功能或者有任何其他查詢，請喺下面同我哋聯絡。",
    "privacy.heading": "私隱政策",
    "privacy.body.before": "呢個應用程式嘅私隱政策係",
    "privacy.link": "呢度",
    "privacy.body.after": "唔該睇下。",
