  dict.privacy["yue"] = {
    "page.title": "醫院/緊急情況理解委員會 — 私隱政策",
    "header.title": "私隱政策",
    "header.subtitle": "醫院/緊急情況理解委員會",
    "header.updated": "上次更新日期",
    "header.date": "2026 年 5 月 20 號",
    "intro": "近藤文和（以下簡稱「開發人員」）認為 iOS 及 Android 版應用程式「醫院 / 緊急和久板」（以下簡稱「應用程式」）嘅用戶私隱保護係極其重要。呢個政策會講解呢個應用程式點樣處理資料。",
    "s1.heading": "1. 要攞到嘅資料",
    "s1.body": "<strong>呢個應用程式唔會收集或者將可以識別個別使用者嘅資料、使用統計資料、醫療資料或者病人資料傳送去開發人員嘅伺服器。</strong>",
    "s2.heading": "2. 儲存喺你部裝置上面嘅資料",
    "s2.body": "呢個應用程式會將以下資料儲存喺使用者嘅裝置上面。呢啲永遠唔會傳送去開發人員嘅伺服器。",
    "s2.item1": "所選顯示語言",
    "s2.item2": "顯示設定，例如 furigana 顯示",
    "s2.item3": "預先錄製嘅醫療詞組同埋用戶編輯/新增嘅詞組",
    "s2.item4": "佢係咪註冊咗做最愛，同埋佢喺最愛入面列出嘅順序",
    "s2.item5": "類別同詞組嘅排序",
    "s2.item6": "iOS 版本嘅應用程式內購買（ Pro 功能）嘅購買狀態",
    "s3.heading": "3. 網絡通訊",
    "s3.body1": "呢個應用程式嘅基本詞組檢視、搜尋、類別顯示、收藏、排序同埋儲存編輯過嘅內容都喺裝置入面運作。",
    "s3.body2": "iOS 版本只會喺購買應用程式內購買或者恢復購買嗰陣同 Apple 嘅伺服器（ StoreKit ）通訊。呢個係用 Apple 營運嘅標準付款平台，而呢個應用程式唔會捕捉任何付款資料。",
    "s4.heading": "4. 向第三方提供資料",
    "s4.body": "呢個應用程式唔會喺開發人員嘅伺服器上面收集使用者嘅個人資料、醫療資料或者病人資料，所以開發人員唔會將呢啲資料提供畀第三方。我哋亦都唔會用第三方媒體庫嚟做廣告、追蹤或者專有分析。",
    "s5.heading": "5. 小朋友用",
    "s5.body": "呢個應用程式唔會喺開發人員嘅伺服器上面收集個人資料，所以所有年齡嘅人都可以用。不過，呢個應用程式係為咗喺醫療環境同埋睇醫生嗰陣協助溝通，而唔係主要為小朋友而設。",
    "s6.heading": "6. 點樣刪除數據",
    "s6.body1": "如果你解除安裝呢個應用程式，系統會刪除儲存喺你裝置上面嘅資料（編輯過嘅短語、收藏、設定等等）。",
    "s6.body2": "iOS 版本嘅應用程式內購買嘅購買記錄會同你嘅 Apple ID 綁定，並儲存喺 Apple 嘅伺服器，你可以喺重新安裝應用程式嗰陣撳一下「還原購買」嚟重新啟動佢。呢個係由 Apple 管理，而唔係個應用程式。",
    "s7.heading": "7. 有關醫療資訊嘅通知",
    "s7.body": "呢個應用程式係一個協助同醫療專業人士進行短訊溝通嘅工具。佢唔係旨在診斷、確定治療計劃或者喺緊急情況下作出判斷。如遇緊急情況，請遵從醫護人員及緊急服務部門指示。",
    "s8.heading": "8. 政策修訂",
    "s8.body": "呢個政策可能會根據需要修訂。如果有任何重要變動，我哋會喺呢個頁面通知你。",
    "back": "← 返去支援頁面",
    "footer.copyright": "© 2026近藤文和。保留所有權利。",
    "s2.android": "Android 版本宜家冇應用程式內購買或者訂閱功能。",
    "s3.body3": "Android 版本唔會喺應用程式內購買或者訂閱嗰陣執行通訊。不過，喺以下情況下，可能會同 Google 或者你裝置嘅系統服務進行通訊：",
    "s3.item1": "下載或者準備一個 ML Kit 翻譯模型",
    "s3.item2": "透過語音輸入搜尋短語",
    "s3.item3": "通過 Android 系統或 Google Play 服務進行診斷和兼容性維護通訊",
    "s3.audio": "Android 版本嘅語音輸入係用嚟用裝置嘅語音識別功能輸入搜尋字詞。呢個應用程式唔會儲存音訊數據。",
    "s4.body2": "但係，喺 Android 版本入面用嘅 Google ML Kit 同埋裝置上面嘅語音識別服務等 SDK 可能會喺 Google 決定嘅範圍內處理裝置資訊、應用程式資訊、錯誤資訊、翻譯設定語言等等，用嚟下載模型、診斷同埋維護質素。呢啲處理方法受 Google 嘅私隱權政策同埋每個服務嘅規格約束。",
    "s6.android": "Android 版本宜家冇應用程式內購買或者訂閱功能。",
    "s9.heading": "9. 聯絡我哋",
    "s9.body": "如果你想知道呢個政策或者呢個應用程式入面嘅資料處理，請喺下面同我哋聯絡。"
  };

